CREATE POLICY "event_prefs_update_own" ON public.event_preferences FOR UPDATE USING (auth.uid() = user_id);
CREATE POLICY "event_prefs_delete_own" ON public.event_preferences FOR DELETE USING (auth.uid() = user_id);

